function CreateShell({
  title,
  subtitle,
  pills,
  fieldIds,
  rowIds,
  shortcuts,
  helpOpen,
  onHelpOpenChange,
  onSubmit,
  onToggleMode,
  submitLabel,
  busy,
  banner,
  preview,
  children,
}: {
  title: string;
  subtitle: ReactNode;
  /** Mode / target toggles, rendered beside the heading. */
  pills?: ReactNode;
  fieldIds: string[];
  rowIds: string[];
  shortcuts: ShortcutSection[];
  helpOpen: boolean;
  onHelpOpenChange: (open: boolean) => void;
  onSubmit: () => void;
  /** ⌘M. Absent on the routes with no auto/manual choice, where the key does nothing. */
  onToggleMode?: () => void;
  submitLabel: string;
  busy: boolean;
  /** What the last submit produced, above the form. */
  banner?: ReactNode;
  preview: ReactNode;
  children: ReactNode;
}): import("react/jsx-runtime").JSX.Element

function SubagentTemplatePreview({
  mode,
  target,
  name,
  idea,
  description,
  triggers,
  tools,
  marketplace,
  marketplacePath,
  plugin,
  projectRoot,
}: {
  mode: "auto" | "manual";
  target: "marketplace" | "project";
  name: string;
  idea: string;
  description: string;
  triggers: string[];
  tools: string[];
  marketplace: string;
  marketplacePath: string;
  plugin: string;
  projectRoot: string;
}): import("react/jsx-runtime").JSX.Element

function SkillTemplatePreview({
  mode,
  target,
  name,
  idea,
  useWhen,
  marketplace,
  marketplacePath,
  plugin,
  projectRoot,
}: {
  mode: "auto" | "manual";
  target: "marketplace" | "project";
  name: string;
  idea: string;
  useWhen: string[];
  marketplace: string;
  /** Absolute path of the selected marketplace, so the preview shows where it really goes. */
  marketplacePath: string;
  plugin: string;
  projectRoot: string;
}): import("react/jsx-runtime").JSX.Element

function MarketplaceManifestPreview({
  name,
  description,
  ownerName,
  ownerEmail,
  homepage,
  targetDir,
}: {
  name: string;
  description: string;
  ownerName: string;
  ownerEmail: string;
  homepage: string;
  targetDir: string;
}): import("react/jsx-runtime").JSX.Element

function PluginManifestPreview({
  name,
  description,
  keywords,
  marketplace,
  marketplacePath,
  owner,
}: {
  name: string;
  description: string;
  keywords: string[];
  marketplace: string;
  marketplacePath: string;
  /** The marketplace's owner, inherited as the plugin's author. Null when it has none. */
  owner: { name: string; email: string } | null;
}): import("react/jsx-runtime").JSX.Element

function CreateResult({
  outcome,
  busy,
  onFinish,
}: {
  outcome: CreateOutcome;
  busy: boolean;
  onFinish: () => void;
}): import("react/jsx-runtime").JSX.Element
